#!/usr/bin/env python3
"""
Minimal agentic loop using Anthropic API with bash execution tool and human confirmation.
"""

import os
import subprocess
import json
from typing import List, Dict, Any
from anthropic import Anthropic


class BashTool:
    """Tool for executing bash commands with human confirmation."""

    @staticmethod
    def get_tool_definition() -> Dict[str, Any]:
        return {
            "name": "run_bash",
            "description": "Execute a bash command on the system",
            "input_schema": {
                "type": "object",
                "properties": {
                    "command": {
                        "type": "string",
                        "description": "The bash command to execute"
                    }
                },
                "required": ["command"]
            }
        }

    @staticmethod
    def execute(command: str) -> Dict[str, Any]:
        """Execute a bash command after human confirmation."""
        print(f"\n⚠️  The agent wants to run the following command:")
        print(f"    $ {command}")

        while True:
            response = input("\nProceed? (y/n): ").lower().strip()
            if response == 'y':
                break
            elif response == 'n':
                return {
                    "success": False,
                    "output": "Command execution denied by user",
                    "error": None
                }
            else:
                print("Please enter 'y' for yes or 'n' for no.")

        try:
            result = subprocess.run(
                command,
                shell=True,
                capture_output=True,
                text=True,
                timeout=30
            )

            return {
                "success": result.returncode == 0,
                "output": result.stdout,
                "error": result.stderr if result.stderr else None
            }
        except subprocess.TimeoutExpired:
            return {
                "success": False,
                "output": "",
                "error": "Command timed out after 30 seconds"
            }
        except Exception as e:
            return {
                "success": False,
                "output": "",
                "error": str(e)
            }


class AgentLoop:
    """Main agent loop for interacting with Anthropic API."""

    def __init__(self, api_key: str):
        self.client = Anthropic(api_key=api_key)
        self.tools = [BashTool.get_tool_definition()]
        self.messages = []

    def run(self):
        """Run the main agent loop."""
        print("🤖 Anthropic Agent Loop Started")
        print("Type 'exit' or 'quit' to end the session\n")

        while True:
            # Get user input
            user_input = input("\n> ").strip()

            if user_input.lower() in ['exit', 'quit']:
                print("\n👋 Goodbye!")
                break

            if not user_input:
                continue

            # Add user message to history
            self.messages.append({
                "role": "user",
                "content": user_input
            })

            # Process with Claude
            self._process_with_claude()

    def _process_with_claude(self):
        """Process the current conversation with Claude."""
        try:
            response = self.client.messages.create(
                model="claude-3-5-sonnet-20241022",
                max_tokens=4096,
                messages=self.messages,
                tools=self.tools
            )

            # Handle tool use
            if response.stop_reason == "tool_use":
                tool_results = []
                assistant_message = {
                    "role": "assistant",
                    "content": response.content
                }
                self.messages.append(assistant_message)

                for content_block in response.content:
                    if content_block.type == "text":
                        print(f"\n🤖 {content_block.text}")
                    elif content_block.type == "tool_use":
                        if content_block.name == "run_bash":
                            command = content_block.input.get("command", "")
                            result = BashTool.execute(command)

                            # Display result
                            if result["success"]:
                                print(f"\n✅ Command executed successfully")
                                if result["output"]:
                                    print(f"Output:\n{result['output']}")
                            else:
                                print(f"\n❌ Command failed")
                                if result["error"]:
                                    print(f"Error: {result['error']}")

                            tool_results.append({
                                "type": "tool_result",
                                "tool_use_id": content_block.id,
                                "content": json.dumps(result)
                            })

                # Send tool results back to Claude
                if tool_results:
                    self.messages.append({
                        "role": "user",
                        "content": tool_results
                    })
                    self._process_with_claude()
            else:
                # Regular text response
                assistant_message = {
                    "role": "assistant",
                    "content": response.content
                }
                self.messages.append(assistant_message)

                for content_block in response.content:
                    if content_block.type == "text":
                        print(f"\n🤖 {content_block.text}")

        except Exception as e:
            print(f"\n❌ Error: {str(e)}")


def main():
    """Main entry point."""
    # Get API key from environment
    api_key = os.environ.get("ANTHROPIC_API_KEY")

    if not api_key:
        print("❌ Please set the ANTHROPIC_API_KEY environment variable")
        print("   export ANTHROPIC_API_KEY='your-api-key-here'")
        return

    # Create and run agent loop
    agent = AgentLoop(api_key)
    agent.run()


if __name__ == "__main__":
    main()

